components.css:
.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 34px;
  padding: 7px 11px;
  border: 1px solid #dce4ee;
  border-radius: 6px;
  background: var(--paper);
  color: var(--foreground);
  font: inherit;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 100ms ease;
}.ds-heading {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.015em;
  margin: 0;
}.ds-seat-item {
  display: flex;
  align-items: center;
  justify-content: start;
  flex-wrap: wrap;
  gap: 5px 9px;
  min-height: 50px;
  padding: 10px 12px;
  text-align: left;
  border-color: var(--line);
  font-weight: 400;
}.ds-seat-item-name {
  font-size: 12px;
  font-weight: 500;
}.ds-seat-item-status {
  font-size: 12px;
  color: var(--muted-foreground);
}.ds-sim-badge {
  margin-left: auto;
  color: #64748b;
  font-size: 9px;
  letter-spacing: 0.03em;
}.ds-seat-item.ds-needs-review {
  background: var(--review-soft);
  border-color: #f1cbc3;
}.ds-seat-item.ds-needs-review .ds-seat-item-status {
  color: var(--review);
  font-weight: 600;
}.ds-seat-item.ds-is-selected {
  border-color: var(--ring);
  outline: 1px solid var(--ring);
  outline-offset: -1px;
}.ds-seat-item{font-family:var(--font-courier-prime,monospace);font-size:14px;
  --background: #fff;
  --foreground: #0f172a;
  --paper: #fff;
  --muted: #f1f5f9;
  --muted-foreground: #64748b;
  --line: #e2e8f0;
  --accent: #eef8f6;
  --accent-foreground: #0f766e;
  --ring: #0f766e;
  --card: #fff;
  --card-foreground: #0f172a;
  --primary: #0f172a;
  --primary-foreground: #fff;
  --secondary: #f1f5f9;
  --secondary-foreground: #0f172a;
  --border: var(--line);
  --input: #cbd5e1;
  --destructive: #b53c2f;
  --destructive-foreground: #fff;
  --review: #b53c2f;
  --review-soft: #fff2ee;
  --radius: 8px;
}.ds-button:focus-visible{outline:2px solid var(--ring,#0f766e);outline-offset:3px;}@media(hover:hover) and (pointer:fine){.ds-seat-item:hover{background:#f1f5f9;}.ds-seat-item.ds-needs-review:hover{background:#ffe9e1;}}@media(max-width:759px){.ds-seat-item{min-height:48px;}}

