  letter-spacing: -0.015em;
  margin: 0;
}.ds-attention-panel {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
}.ds-panel-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  min-height: 46px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}.ds-attention-count {
  color: var(--muted-foreground);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}.ds-attention-count.ds-has-items {
  color: var(--review);
  font-weight: 600;
}.ds-attention-list {
  padding: 0;
  margin: 0;
  list-style: none;
}.ds-attention-list li {
  padding: 20px 16px;
  border-bottom: 1px solid var(--line);
}.ds-attention-item-heading {
  display: flex;
  align-items: start;
  flex-wrap: wrap;
  gap: 8px;
}.ds-attention-item-heading h3 {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
}.ds-review-label {
  color: var(--review);
  background: var(--review-soft);
  border-radius: 4px;
  padding: 2px 5px;
  font-size: 10px;
  font-weight: 500;
}.ds-attention-list li > p {
  color: var(--muted-foreground);
  font-size: 13px;
  line-height: 1.6;
  margin: 10px 0 16px;
  max-width: 42ch;
}.ds-attention-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}.ds-attention-actions > button {
  min-height: 32px;
  font-size: 12px;
}.ds-text-button {
  border-color: transparent;
  background: transparent;
  font-size: 12px;
  font-weight: 400;
  color: var(--muted-foreground);
  padding: 5px 7px;
  min-height: 30px;
